package main

import (
	"os/exec"
	"fmt"
)

func main() {
	_, err := exec.LookPath("tsc")
	if err != nil {
		fmt.Println("TypeScript compiler (tsc) is not installed.")
	} else {
		fmt.Println("TypeScript compiler (tsc) is available.")
	}

	_, err = exec.LookPath("g++")
	if err != nil {
		fmt.Println("C++ compiler (g++) is not installed.")
	} else {
		fmt.Println("C++ compiler (g++) is available.")
	}
}
